import React, { useState } from "react";

function PuppyDetailView({ puppy }) {
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleFormSubmit = async (e) => {
    e.preventDefault();

    const form = e.currentTarget;
    setIsSubmitting(true);

    try {
      const response = await fetch(
        "https://formspree.io/f/xbggrkyr",
        {
          method: "POST",
          body: new FormData(form),
          headers: {
            Accept: "application/json",
          },
        }
      );

      if (response.ok) {
        alert("Your enquiry has been submitted successfully!");
        form.reset();
      } else {
        const result = await response.json();
        alert(
          result.errors?.map((error) => error.message).join(", ") ||
            "Unable to submit your enquiry. Please try again."
        );
      }
    } catch (error) {
      console.error("Form submission error:", error);
      alert("Something went wrong. Please check your internet connection.");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (!puppy) {
    return <p>Puppy details are not available.</p>;
  }

  return (
    <div className="puppy-detail-container">
      <div className="puppy-detail-image">
        <img
          src={puppy.image}
          alt={puppy.name}
        />
      </div>

      <div className="puppy-detail-info">
        <h1>{puppy.name}</h1>
        <p><strong>Breed:</strong> {puppy.breed}</p>
        <p><strong>Gender:</strong> {puppy.gender}</p>
        <p><strong>Age:</strong> {puppy.age}</p>
        <p><strong>Location:</strong> {puppy.where}</p>

        <h2>Interested in this puppy?</h2>
        <p>Fill out the form and we will contact you.</p>

        <form onSubmit={handleFormSubmit}>
          <input
            type="text"
            name="customerName"
            placeholder="Your Full Name"
            required
          />

          <input
            type="email"
            name="email"
            placeholder="Your Email Address"
            required
          />

          <input
            type="tel"
            name="phone"
            placeholder="Your WhatsApp Number"
            required
          />

          <input
            type="hidden"
            name="puppyName"
            value={puppy.name || ""}
          />

          <input
            type="hidden"
            name="breed"
            value={puppy.breed || ""}
          />

          <button type="submit" disabled={isSubmitting}>
            {isSubmitting ? "Submitting..." : "Submit Enquiry"}
          </button>
        </form>
      </div>
    </div>
  );
}

export default PuppyDetailView;
